/**
 * Cascade behind `ProjectService.archiveProject`; returns the number of issues
 * it archived. Only live issues are stamped: an issue archived earlier keeps
 * its original `archived_at` (so retention is not pushed back) and is not
 * counted, which keeps the event and the usage meter in step with live rows.
 */
export async function archiveIssuesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const rows = getDb()
    .update(issues)
    .set(archivePatch())
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .returning({ id: issues.id })
    .all();

  return rows.length;
}

