it("archives only the live issues and leaves earlier archives untouched", async () => {
  const tenant = await createTenant("archivemixed", "growth");

  const handArchived = await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, { title: "Archived by hand" }),
  );
  await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, { title: "Still live" }),
  );

  const earlier = await issueService.archiveIssue(
    tenant.actors.member,
    tenant.org.id,
    handArchived.id,
  );
  // Make sure the cascade would produce a different timestamp if it wrote one.
  await new Promise((resolve) => setTimeout(resolve, 10));

  const received: unknown[] = [];
  const off = subscribe("project.archived", (payload) => {
    received.push(payload);
  });

  try {
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: true,
    });

    expect(received).toHaveLength(1);
    expect(received[0]).toMatchObject({ issuesArchived: 1 });
  } finally {
    off();
  }

  const after = await issueRepo.findIssueById(tenant.org.id, handArchived.id);
  expect(after?.archivedAt).toBe(earlier.archivedAt);
  await expect(
    issueRepo.countIssues(tenant.org.id, tenant.project.id, {
      includeArchived: true,
    }),
  ).resolves.toBe(2);
});

